# apl-source:14
#     اطبع "ناجح:", اسم
# apl-source:15

# apl-source:16
def تأكد_يساوي(فعلي, متوقع, اسم):
  # apl-source:17
  if فعلي != متوقع:
    # apl-source:18
    print("فشل:", اسم)
    # apl-source:19
    print("  متوقع:", متوقع)
    # apl-source:20
    print("  فعلي:", فعلي)
    # apl-source:21
    قياسي_نظام_اخرج(1)
  # apl-source:22
  print("ناجح:", اسم)
# apl-source:23

# apl-source:24
# منحنيات بيزييه التربيعية والتكعيبية
# apl-source:25
# Demonstrates: كاستلجو, أوزان برنشتاين, تقييم عند ت
# apl-source:26
# نقطة المنتصف لمنحنى تكعيبي متماثل تقع في منتصف الرأس
# apl-source:27

# apl-source:28
def بيزييه_تربيعي(ن0, ن1, ن2, ت):
  # apl-source:29
  س = (1 - ت) * (1 - ت) * ن0[0] + 2 * (1 - ت) * ت * ن1[0] + ت * ت * ن2[0]
  # apl-source:30
  ع = (1 - ت) * (1 - ت) * ن0[1] + 2 * (1 - ت) * ت * ن1[1] + ت * ت * ن2[1]
  # apl-source:31
  return [س, ع]
# apl-source:32

# apl-source:33
def بيزييه_تكعيبي(ن0, ن1, ن2, ن3, ت):
  # apl-source:34
  ق = 1 - ت
  # apl-source:35
  س = ق * ق * ق * ن0[0] + 3 * ق * ق * ت * ن1[0] + 3 * ق * ت * ت * ن2[0] + ت * ت * ت * ن3[0]
  # apl-source:36
  ع = ق * ق * ق * ن0[1] + 3 * ق * ق * ت * ن1[1] + 3 * ق * ت * ت * ن2[1] + ت * ت * ت * ن3[1]
  # apl-source:37
  return [س, ع]
# apl-source:38

# apl-source:39
نق = بيزييه_تكعيبي([0, 0], [1, 2], [3, 2], [4, 0], 0.5)
# apl-source:40
تأكد_يساوي(نق, [2.0, 1.5], "منتصف التكعيبي")
# apl-source:41
تأكد_يساوي(بيزييه_تكعيبي([0, 0], [1, 2], [3, 2], [4, 0], 0.0), [0, 0], "البداية")
# apl-source:42
تأكد_يساوي(بيزييه_تكعيبي([0, 0], [1, 2], [3, 2], [4, 0], 1.0), [4, 0], "النهاية")
# apl-source:43
ت2 = بيزييه_تربيعي([0, 0], [2, 4], [4, 0], 0.5)
# apl-source:44
تأكد_يساوي(ت2, [2.0, 2.0], "منتصف التربيعي")
# apl-source:45
تأكد_يساوي(بيزييه_تربيعي([0, 0], [2, 4], [4, 0], 0.25), [1.0, 1.5], "ربع التربيعي")
# apl-source:46
print("منتصف:", نق)
# apl-source:47
